EXTRA = {'7071': {'de':{'das Quad':'квадроцикл'},'es':{'el quad':'квадроцикл'},'fr':{'le quad':'квадроцикл'}}}
for lang, d in D.items():
    src = json.load(open(f'{H}/tr/source_{lang}.json'))
    out = {}
    for vid, s in src.items():
        ph, no, q, a, caps = d[vid]
        assert len(ph)==3 and len(no)==len(s['nouns']) and len(caps)==len(s['captions'])
        m = {p['text']: t for p, t in zip(s['phrases'], ph)}
        m.update(dict(zip(s['captions'], caps)))
        m.update(EXTRA.get(vid, {}).get(lang, {}))
        # answer row: answer without pronoun and final period
        m[s['answer'].split(' ',1)[1].rstrip('.') .lower() if False else None] = None
        ans_row = a.split(' ',1)[1].rstrip('.')
        rec = []
        for r in s['recall']:
            if r in m and m[r]: rec.append(m[r])
            else: rec.append(ans_row)  # the only non-mapped row is the answer row
        assert sum(1 for r in s['recall'] if r not in m) == 1, (lang, vid, [r for r in s['recall'] if r not in m])
        out[vid] = {'phrases': ph, 'nouns': no, 'question': q, 'answer': a,
                    'captions': dict(zip(s['captions'], caps)), 'recall': rec}
    os.makedirs(f'{H}/tr/{lang}', exist_ok=True)
    json.dump(out, open(f'{H}/tr/{lang}/ua.json','w'), ensure_ascii=False, indent=1)
